-- Encrypted loader. Do not edit by hand.
local function b64decode(data)
    local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    data = string.gsub(data, '[^'..b..'=]', '')
    return (data:gsub('.', function(x)
        if (x == '=') then return '' end
        local r,f='',(b:find(x)-1)
        for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0') end
        return r
    end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)
        if (#x ~= 8) then return '' end
        local c=0
        for i=1,8 do c=c+(x:sub(i,i)=='1' and 2^(8-i) or 0) end
        return string.char(c)
    end))
end

-- Pure-arithmetic XOR (no bit32/bit library, no 5.3-only "~" operator,
-- so this runs on Lua 5.1, 5.2, 5.3 and 5.4 alike).
local function bxor(a, b)
    local r, p = 0, 1
    while a > 0 or b > 0 do
        local da, db = a % 2, b % 2
        if da ~= db then r = r + p end
        a = (a - da) / 2
        b = (b - db) / 2
        p = p * 2
    end
    return r
end

local KEY = "BenLoader_2026_Key"
local ENC = ""

local function xorDecrypt(data, key)
    local out = {}
    for i = 1, #data do
        local kb = string.byte(key, ((i - 1) % #key) + 1)
        local db = string.byte(data, i)
        out[i] = string.char(bxor(db, kb))
    end
    return table.concat(out)
end

local raw = b64decode(ENC)
local src = xorDecrypt(raw, KEY)
local fn, err = load(src)
if not fn then
    error("Decrypt/load failed: " .. tostring(err))
end
return fn()
